    private static readonly int _hash = DefaultReactions.Aggregate(0, (h, r) => h * 31 + ((TAvailableReaction)r).Reaction.GetHashCode()) & int.MaxValue;

    protected override Task<MyTelegram.Schema.Messages.IAvailableReactions> HandleCoreAsync(IRequestInput input, MyTelegram.Schema.Messages.RequestGetAvailableReactions obj)
    {
        if (obj.Hash != 0 && obj.Hash == _hash)
            return Task.FromResult<IAvailableReactions>(new TAvailableReactionsNotModified());
        return Task.FromResult<IAvailableReactions>(new TAvailableReactions
        {
            Reactions = new TVector<IAvailableReaction>(DefaultReactions),
            Hash = _hash
        });
    }
